<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php';
$pdo=getConnection(); $tipos=$pdo->query('SELECT id_tipo,nome_tipo FROM tipo_ocorrencia ORDER BY nome_tipo')->fetchAll();
$rows=$pdo->query("SELECT o.id_ocorrencia,o.latitude,o.longitude,o.descricao,o.data,o.horario,t.nome_tipo,o.id_tipo FROM ocorrencia o JOIN tipo_ocorrencia t ON t.id_tipo=o.id_tipo WHERE o.status='aprovada' ORDER BY o.id_ocorrencia DESC")->fetchAll();
$page_title='SafeRoute — Mapa de ocorrências';$extra_css=['https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'];$extra_js=['https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'];require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/navbar.php'; ?>
<main class="container page-main"><section class="page-hero"><span class="eyebrow">MAPA</span><h1>Mapa de ocorrências</h1><p>Visualize ocorrências aprovadas e filtre os dados por categoria.</p></section><section class="card" style="margin-bottom:20px"><div class="admin-search"><select id="tipoFiltro" class="form-control"><option value="">Todos os tipos</option><?php foreach($tipos as $t): ?><option value="<?= $t['id_tipo'] ?>"><?= htmlspecialchars($t['nome_tipo']) ?></option><?php endforeach; ?></select><button class="btn btn-primary" id="filtrarMapa" type="button">Filtrar</button></div></section><div id="safeMap" class="safe-map"></div><p class="map-info"><strong id="mapCount"><?= count($rows) ?></strong> ocorrência(s) aprovada(s). <span class="muted">Risco estimado baseado nos dados disponíveis.</span></p></main>
<script>document.addEventListener('DOMContentLoaded',()=>{const data=<?= json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;const map=L.map('safeMap').setView([-8.7612,-63.9004],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);let markers=[];function esc(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function render(){markers.forEach(m=>map.removeLayer(m));markers=[];const f=document.getElementById('tipoFiltro').value;const filtered=f?data.filter(o=>String(o.id_tipo)===f):data;const b=[];filtered.forEach(o=>{const lat=+o.latitude,lng=+o.longitude;if(!isFinite(lat)||!isFinite(lng))return;const m=L.marker([lat,lng]).addTo(map);m.bindPopup('<b>'+esc(o.nome_tipo)+'</b><br>'+esc(o.descricao||'Sem descrição')+'<br><small>'+esc(o.data)+' '+esc(o.horario)+'</small>');markers.push(m);b.push([lat,lng])});document.getElementById('mapCount').textContent=filtered.length;if(b.length)map.fitBounds(b,{padding:[30,30],maxZoom:16});else map.setView([-8.7612,-63.9004],13)}render();document.getElementById('filtrarMapa').onclick=render;});</script><?php require_once __DIR__.'/../includes/footer.php'; ?>